// =============================================================================
// lib/main.dart
//
// OWNER: Lead. Single app, role-based routing (per the locked product split):
//
//   /            → RoleSelectScreen (hackathon stand-in for login)
//   /reporter    → lib/features/reporter/     (Friend 1)
//   /dispatcher  → lib/features/dispatcher/  (Friend 2)
//   /crew        → lib/features/crew/        (Friend 3)
//
// Feature teammates: do NOT edit this file. Read everything you need from
// `CoreScope` inside your screen (session, api, board). The three imports below
// are the only integration points — class names and zero-arg constructors are
// the frozen contract.
//
// Run against your laptop (compiled-in, no runtime config):
//   flutter run \
//     --dart-define=API_BASE=https://192.168.1.50:8443 \
//     --dart-define=API_TOKEN=demo-token
// Emergency dev-only fallback (plain HTTP, accepts any cert):
//   flutter run --dart-define=API_BASE=http://192.168.1.50:8080 \
//               --dart-define=DEV_INSECURE=true
// =============================================================================

import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart' show rootBundle;

import 'core/api/api_client.dart';
import 'core/auth/token_store.dart';
import 'core/core_scope.dart';
import 'core/incidents/taxonomy.dart';
import 'core/models/session.dart';
import 'core/state/ticket_board.dart';
import 'features/crew/crew_screen.dart';
import 'features/dispatcher/dispatcher_screen.dart';
import 'features/reporter/reporter_screen.dart';

/// Laptop LAN address + port serving HTTPS/WSS. Overridden per build:
///   --dart-define=API_BASE=https://192.168.1.50:8443
const String kApiBase = String.fromEnvironment(
  'API_BASE',
  defaultValue: 'https://wingman.local:8443',
);

/// Demo bearer token; must match `API_TOKEN` on the backend.
const String kApiToken = String.fromEnvironment(
  'API_TOKEN',
  defaultValue: 'demo-token',
);

/// DEV ONLY. Accepts any TLS certificate. Keep false for the judged demo.
const bool kDevInsecure = bool.fromEnvironment(
  'DEV_INSECURE',
  defaultValue: false,
);

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();

  // Fail fast during development if someone edits the taxonomy into an
  // invalid state (wrong count, duplicate code, empty department list).
  assert(() {
    IncidentTaxonomy.validate();
    return true;
  }());
  debugPrint(
    '[boot] taxonomy v${IncidentTaxonomy.schemaVersion}: '
    '${IncidentTaxonomy.all.length} types, API=$kApiBase, insecure=$kDevInsecure',
  );

  final caPem = await _loadCaPem();
  final api = ApiClient(
    baseUrl: kApiBase,
    token: kApiToken,
    caPem: caPem,
    allowInsecure: kDevInsecure,
  );

  // Swap for SecureTokenStore once flutter_secure_storage is in pubspec
  // (see lib/core/auth/secure_token_store.dart).
  final tokenStore = MemoryTokenStore(kApiToken);
  final board = TicketBoard(api: api);

  runApp(AirportApp(api: api, board: board, tokenStore: tokenStore));
}

/// Loads the self-signed CA bundled as a Flutter asset. Missing asset is a
/// warning, not a crash: the app still boots and shows an actionable error.
Future<String?> _loadCaPem() async {
  try {
    final pem = await rootBundle.loadString('assets/certs/ca.crt');
    if (pem.trim().isEmpty) {
      debugPrint('[cert] assets/certs/ca.crt is empty.');
      return null;
    }
    return pem;
  } on Object catch (error) {
    debugPrint(
      '[cert] assets/certs/ca.crt missing ($error). Run '
      'scripts/gen_certs.ps1, then `flutter pub get`. Until then only '
      '--dart-define=DEV_INSECURE=true will work.',
    );
    return null;
  }
}

class AirportApp extends StatefulWidget {
  const AirportApp({
    super.key,
    required this.api,
    required this.board,
    required this.tokenStore,
  });

  final ApiClient api;
  final TicketBoard board;
  final TokenStore tokenStore;

  @override
  State<AirportApp> createState() => _AirportAppState();
}

class _AirportAppState extends State<AirportApp> {
  final GlobalKey<NavigatorState> _navigatorKey = GlobalKey<NavigatorState>();
  Session? _session;

  @override
  void initState() {
    super.initState();
    // One WSS connection for the whole app lifetime; the board fans events out
    // to every screen through ListenableBuilder.
    unawaited(widget.board.start());
  }

  @override
  void dispose() {
    widget.board.dispose();
    unawaited(widget.api.close());
    super.dispose();
  }

  void _selectRole(Session session) {
    setState(() => _session = session);
    _navigatorKey.currentState?.pushReplacementNamed(session.role.route);
  }

  void _signOut() {
    setState(() => _session = null);
    _navigatorKey.currentState?.pushNamedAndRemoveUntil('/', (route) => false);
  }

  @override
  Widget build(BuildContext context) {
    return CoreScope(
      api: widget.api,
      board: widget.board,
      tokenStore: widget.tokenStore,
      session: _session,
      onSignOut: _signOut,
      child: MaterialApp(
        title: 'Wingman',
        debugShowCheckedModeBanner: false,
        navigatorKey: _navigatorKey,
        theme: ThemeData(
          useMaterial3: true,
          colorSchemeSeed: const Color(0xFF0B5FFF),
          brightness: Brightness.light,
        ),
        initialRoute: '/',
        routes: <String, WidgetBuilder>{
          '/': (context) => _roleSelect(),
          UserRole.reporter.route: (context) => _guard(const ReporterScreen()),
          UserRole.dispatcher.route: (context) =>
              _guard(const DispatcherScreen()),
          UserRole.crew.route: (context) => _guard(const CrewScreen()),
        },
      ),
    );
  }

  /// Prevents a cold deep-link into a feature screen before a role is chosen
  /// (which would throw in `CoreScope.sessionOf`).
  Widget _guard(Widget screen) =>
      _session == null ? _roleSelect() : screen;

  Widget _roleSelect() => RoleSelectScreen(onRoleSelected: _selectRole);
}

/// Hackathon stand-in for auth: pick a role, get a demo session. The real token
/// comes from `--dart-define=API_TOKEN`, never from this screen.
class RoleSelectScreen extends StatefulWidget {
  const RoleSelectScreen({super.key, required this.onRoleSelected});

  /// Created by `main.dart`; hands the chosen demo session back to the router.
  final ValueChanged<Session> onRoleSelected;

  @override
  State<RoleSelectScreen> createState() => _RoleSelectScreenState();
}

class _RoleSelectScreenState extends State<RoleSelectScreen> {
  final TextEditingController _nameController = TextEditingController();

  @override
  void dispose() {
    _nameController.dispose();
    super.dispose();
  }

  void _pick(UserRole role) {
    widget.onRoleSelected(
      Session.demo(role, displayName: _nameController.text),
    );
  }

  @override
  Widget build(BuildContext context) {
    final board = CoreScope.boardOf(context);
    final theme = Theme.of(context);

    return Scaffold(
      body: SafeArea(
        child: ListenableBuilder(
          listenable: board,
          builder: (context, _) {
            final online = board.connected;
            return SingleChildScrollView(
              padding: const EdgeInsets.all(24),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: <Widget>[
                  const SizedBox(height: 24),
                  Text(
                    'Wingman',
                    style: theme.textTheme.headlineMedium
                        ?.copyWith(fontWeight: FontWeight.w700),
                  ),
                  const SizedBox(height: 6),
                  Text(
                    'Raportare incidente · dispecerat · echipaje',
                    style: theme.textTheme.bodyMedium
                        ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
                  ),
                  const SizedBox(height: 24),
                  TextField(
                    controller: _nameController,
                    textInputAction: TextInputAction.done,
                    decoration: const InputDecoration(
                      labelText: 'Nume (opțional)',
                      hintText: 'ex. Andrei P.',
                      border: OutlineInputBorder(),
                    ),
                  ),
                  const SizedBox(height: 20),
                  _RoleCard(
                    icon: Icons.record_voice_over_outlined,
                    title: UserRole.reporter.labelRo,
                    subtitle: 'Raportează prin voce sau meniu',
                    onTap: () => _pick(UserRole.reporter),
                  ),
                  const SizedBox(height: 12),
                  _RoleCard(
                    icon: Icons.dashboard_outlined,
                    title: UserRole.dispatcher.labelRo,
                    subtitle: 'Confirmă, respinge, supraveghează',
                    onTap: () => _pick(UserRole.dispatcher),
                  ),
                  const SizedBox(height: 12),
                  _RoleCard(
                    icon: Icons.engineering_outlined,
                    title: UserRole.crew.labelRo,
                    subtitle: 'Preia, votează rezolvarea',
                    onTap: () => _pick(UserRole.crew),
                  ),
                  const SizedBox(height: 28),
                  Row(
                    children: <Widget>[
                      Icon(
                        online ? Icons.wifi : Icons.wifi_off,
                        size: 16,
                        color: online ? Colors.green.shade700 : Colors.red,
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          online
                              ? 'Server conectat · ${board.tickets.length} tichete'
                              : 'Server offline — verifică IP-ul, Wi-Fi-ul și firewall-ul',
                          style: theme.textTheme.bodySmall,
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 12),
                  SelectableText(
                    'API: $kApiBase',
                    style: theme.textTheme.bodySmall?.copyWith(
                      color: theme.colorScheme.onSurfaceVariant,
                      fontFamily: 'monospace',
                    ),
                  ),
                  if (board.lastError != null) ...<Widget>[
                    const SizedBox(height: 8),
                    Text(
                      board.lastError!,
                      style: theme.textTheme.bodySmall
                          ?.copyWith(color: theme.colorScheme.error),
                    ),
                  ],
                ],
              ),
            );
          },
        ),
      ),
    );
  }
}

class _RoleCard extends StatelessWidget {
  const _RoleCard({
    required this.icon,
    required this.title,
    required this.subtitle,
    required this.onTap,
  });

  final IconData icon;
  final String title;
  final String subtitle;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Card(
      margin: EdgeInsets.zero,
      child: ListTile(
        onTap: onTap,
        leading: Icon(icon, size: 28),
        title: Text(
          title,
          style: theme.textTheme.titleMedium
              ?.copyWith(fontWeight: FontWeight.w600),
        ),
        subtitle: Text(subtitle),
        trailing: const Icon(Icons.chevron_right),
        contentPadding:
            const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
      ),
    );
  }
}
